$line = (Get-Content "C:\Users\Home\ISOMTRIC\assets\ISOMTRIC.html")[955]; 
# Extract front male paths
$mFront = [regex]::Match($line, '"front":\{"vb":"([^"]+)","p":(\[.+\])');
Write-Output "--- FRONT VIEWBOX ---"
Write-Output "Male front viewBox: $($mFront.Groups[1].Value)"

# Extract back male paths - find the "back" key
$mBack = [regex]::Match($line, '"back":\{"vb":"([^"]+)","p":(\[.+\])');
Write-Output "--- BACK VIEWBOX ---"
Write-Output "Male back viewBox: $($mBack.Groups[1].Value)"

$urls = @(
  @{url='https://raw.githubusercontent.com/melihcolpan/MuscleMap/main/Screenshots/male_front_highlight.png'; name='male-front.png'},
  @{url='https://raw.githubusercontent.com/melihcolpan/MuscleMap/main/Screenshots/male_back_highlight.png'; name='male-back.png'}
); foreach($u in $urls) { try { Invoke-WebRequest -Uri $u.url -OutFile "assets\images\body\$($u.name)"; Write-Output "downloaded: $($u.name)" } catch { Write-Output "failed: $($u.name) - $_" } }
